// "Surprise me" in the art studio: a random picture made of the studio's own shapes. Each kind
// (a night sky, mountains, waves, tiles, cut paper, orbits, a rosette) is a composition with rules
// of its own, coloured from a palette picked to go together, and rolled from a seed, so the same
// seed and size always make the same picture.
//
// It's procedural, not generated by AI: nothing is learned or fetched, and the result is ordinary
// shapes, in named groups, that the writer can pick apart, recolour and draw over. No DOM, so it
// can be tested alone.

import {
	IDENTITY,
	newId,
	solid,
	type Anchor,
	type LineCap,
	type LineJoin,
	type Matrix,
	type Shape,
	type Stroke,
	type Subpath
} from '$lib/drawing';
import { parseHex, rgbToHsv, toHex } from './color';
import { transformSubpaths, type Point } from './geometry';

export const SURPRISES = [
	{ key: 'night', label: 'Night sky' },
	{ key: 'mountains', label: 'Mountains' },
	{ key: 'waves', label: 'Waves' },
	{ key: 'tiles', label: 'Tiles' },
	{ key: 'cutouts', label: 'Cut paper' },
	{ key: 'orbits', label: 'Orbits' },
	{ key: 'rosette', label: 'Rosette' }
] as const;

export type SurpriseKind = (typeof SURPRISES)[number]['key'];
export type Surprise = { kind: SurpriseKind; label: string; seed: number; shapes: Shape[] };

/**
 * A random picture the size of a drawing. `kind` picks what it is ('any' for a surprise of a
 * surprise, which won't be `avoid`, the last one), and `seed` makes it again.
 */
export function surprise(
	width: number,
	height: number,
	options: { kind?: SurpriseKind | 'any'; seed?: number; avoid?: SurpriseKind | null } = {}
): Surprise {
	const seed = (options.seed ?? randomSeed()) >>> 0;
	const roll = new Roll(seed);
	const kind =
		!options.kind || options.kind === 'any'
			? chooseKind(roll, width / height, options.avoid)
			: options.kind;
	const label = SURPRISES.find((item) => item.key === kind)!.label;
	return { kind, label, seed, shapes: MAKERS[kind](roll, width, height) };
}

export function randomSeed() {
	const value = new Uint32Array(1);
	crypto.getRandomValues(value);
	return value[0];
}

/** Very wide drawings (ornaments, banners) suit some kinds better than others. */
const WIDE: Record<SurpriseKind, number> = {
	night: 1,
	mountains: 2,
	waves: 2,
	tiles: 1,
	cutouts: 1,
	orbits: 1,
	rosette: 3
};

function chooseKind(roll: Roll, ratio: number, avoid?: SurpriseKind | null): SurpriseKind {
	const weights = SURPRISES.map((item) =>
		item.key === avoid ? 0 : ratio > 2.2 ? WIDE[item.key] : 1
	);
	let left = roll.next() * weights.reduce((sum, weight) => sum + weight, 0);
	for (let index = 0; index < SURPRISES.length; index++) {
		left -= weights[index];
		if (left < 0) return SURPRISES[index].key;
	}
	return SURPRISES[0].key;
}

// ---- Chance ------------------------------------------------------------------------------------

/** A seeded random (mulberry32): small, quick, and the same everywhere. */
class Roll {
	#state: number;

	constructor(seed: number) {
		this.#state = seed >>> 0;
	}

	/** From 0 up to 1. */
	next() {
		this.#state = (this.#state + 0x6d2b79f5) >>> 0;
		let t = this.#state;
		t = Math.imul(t ^ (t >>> 15), t | 1);
		t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
		return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
	}

	range(min: number, max: number) {
		return min + (max - min) * this.next();
	}

	/** A whole number from min to max, both included. */
	int(min: number, max: number) {
		return Math.min(max, Math.floor(this.range(min, max + 1)));
	}

	chance(odds: number) {
		return this.next() < odds;
	}

	pick<T>(items: readonly T[]): T {
		return items[Math.min(items.length - 1, Math.floor(this.next() * items.length))];
	}

	shuffle<T>(items: readonly T[]): T[] {
		const list = [...items];
		for (let index = list.length - 1; index > 0; index--) {
			const other = Math.floor(this.next() * (index + 1));
			[list[index], list[other]] = [list[other], list[index]];
		}
		return list;
	}
}

// ---- Colour ------------------------------------------------------------------------------------

/** Colours that go together. Each is sorted dark to light when it's used. */
const PALETTES = [
	['#0d1330', '#1f4e6b', '#2b63f5', '#7cb4ff', '#f5f0e6'], // the workshop at night
	['#1d2142', '#2b63f5', '#e0603a', '#e8b04b', '#f5f0e6'], // primaries on paper
	['#2a0f12', '#7a1f1f', '#b4471b', '#e8b04b', '#f6e7c8'], // embers
	['#0f2a33', '#1f5f6b', '#3f8f8a', '#a9d6c6', '#eef4ea'], // sea glass
	['#16261b', '#2f5d3a', '#6f9a5b', '#a9c47f', '#efe8d0'], // forest
	['#1d1638', '#5b3f8c', '#b0124f', '#e88fa6', '#f8d9c0'], // dusk
	['#3b2416', '#5a7d8c', '#a8774a', '#d9a066', '#f1e4cc'], // desert
	['#15161c', '#4a4e69', '#8d8fa3', '#c9b99a', '#f5f0e6'], // ink and paper
	['#264653', '#2a9d8f', '#e76f51', '#f4a261', '#e9c46a'], // harbour
	['#2b1e3f', '#6c3f7a', '#c86b98', '#f2b880', '#fbe9d7'], // plum
	['#0b1d3a', '#24507a', '#5c9ccc', '#bfe0f2', '#ffffff'], // glacier
	['#3d1e0f', '#8c3b18', '#6b8f71', '#d9822b', '#f2c14e'], // autumn
	['#05445e', '#189ab4', '#75e6da', '#f9c74f', '#f4f9f4'], // lagoon
	['#2d3a2e', '#7a8b5a', '#d98c8c', '#f2c4b8', '#faf3e8'], // rose and moss
	['#070b1f', '#1b2552', '#3c4a8a', '#c9a227', '#f3e3b3'], // midnight and gold
	['#3a2a20', '#c05a3c', '#e2a36b', '#8fb3a8', '#f4ead9'] // terracotta
];

const BLACK = '#000000ff';
const WHITE = '#ffffffff';

/** A colour as #rrggbbaa, with its transparency set. */
const tint = (color: string, alpha = 1) => toHex({ ...parseHex(color), a: alpha });

function mix(from: string, to: string, amount: number) {
	const a = parseHex(from);
	const b = parseHex(to);
	const t = Math.max(0, Math.min(1, amount));
	return toHex({
		r: a.r + (b.r - a.r) * t,
		g: a.g + (b.g - a.g) * t,
		b: a.b + (b.b - a.b) * t,
		a: a.a + (b.a - a.a) * t
	});
}

const lightness = (color: string) => {
	const { r, g, b } = parseHex(color);
	return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

/** A colour partway along a list of them, 0 the first and 1 the last. */
function along(colors: string[], amount: number) {
	const at = Math.max(0, Math.min(1, amount)) * (colors.length - 1);
	const index = Math.min(colors.length - 2, Math.floor(at));
	return mix(colors[index], colors[index + 1], at - index);
}

/** The palette's liveliest colour, past its darkest. */
function accent(tones: string[]) {
	let best = tones[tones.length - 1];
	let score = -1;
	for (const color of tones.slice(1)) {
		const { s, v } = rgbToHsv(parseHex(color));
		if (s * v > score) {
			score = s * v;
			best = color;
		}
	}
	return best;
}

const paletteOf = (roll: Roll) =>
	roll
		.pick(PALETTES)
		.map((color) => tint(color))
		.sort((a, b) => lightness(a) - lightness(b));

// ---- Shapes ------------------------------------------------------------------------------------

const TURN = Math.PI * 2;
/** Two places is what the cleaner keeps; `|| 0` turns -0 into 0. */
const r2 = (value: number) => Math.round(value * 100) / 100 || 0;
const r6 = (value: number) => Math.round(value * 1e6) / 1e6 || 0;
const side = (value: number) => Math.max(0.01, r2(value));

function base(name: string, transform: Matrix = [...IDENTITY], opacity = 1) {
	return {
		id: newId(),
		name,
		transform,
		opacity: Math.round(Math.max(0, Math.min(1, opacity)) * 1000) / 1000,
		hidden: false,
		locked: false
	};
}

/** Puts a box's top left at (x, y), then turns it by angle about its centre. */
function boxAt(x: number, y: number, width: number, height: number, angle = 0): Matrix {
	const cos = Math.cos(angle);
	const sin = Math.sin(angle);
	const cx = x + width / 2;
	const cy = y + height / 2;
	return [
		r6(cos),
		r6(sin),
		r6(-sin),
		r6(cos),
		r2(cx - (width / 2) * cos + (height / 2) * sin),
		r2(cy - (width / 2) * sin - (height / 2) * cos)
	];
}

function strokeOf(
	color: string,
	width: number,
	options: { dash?: number[]; cap?: LineCap; join?: LineJoin } = {}
): Stroke {
	return {
		paint: solid(color),
		width: Math.max(0.1, r2(width)),
		cap: options.cap ?? 'round',
		join: options.join ?? 'round',
		dash: options.dash ?? []
	};
}

type Look = { stroke?: Stroke | null; opacity?: number; angle?: number };

const fillOf = (color: string | null) => (color ? solid(color) : null);

function rect(
	name: string,
	x: number,
	y: number,
	width: number,
	height: number,
	fill: string | null,
	look: Look & { radius?: number } = {}
): Shape {
	return {
		...base(name, boxAt(x, y, width, height, look.angle), look.opacity),
		kind: 'rect',
		width: side(width),
		height: side(height),
		radius: r2(look.radius ?? 0),
		fill: fillOf(fill),
		stroke: look.stroke ?? null
	};
}

function ellipse(
	name: string,
	cx: number,
	cy: number,
	rx: number,
	ry: number,
	fill: string | null,
	look: Look = {}
): Shape {
	return {
		...base(name, boxAt(cx - rx, cy - ry, rx * 2, ry * 2, look.angle), look.opacity),
		kind: 'ellipse',
		width: side(rx * 2),
		height: side(ry * 2),
		fill: fillOf(fill),
		stroke: look.stroke ?? null
	};
}

const circle = (
	name: string,
	cx: number,
	cy: number,
	radius: number,
	fill: string | null,
	look: Look = {}
) => ellipse(name, cx, cy, radius, radius, fill, look);

function star(
	name: string,
	cx: number,
	cy: number,
	radius: number,
	points: number,
	inner: number,
	fill: string | null,
	look: Look = {}
): Shape {
	return {
		...base(
			name,
			boxAt(cx - radius, cy - radius, radius * 2, radius * 2, look.angle),
			look.opacity
		),
		kind: 'star',
		width: side(radius * 2),
		height: side(radius * 2),
		points,
		inner: Math.round(inner * 1000) / 1000,
		fill: fillOf(fill),
		stroke: look.stroke ?? null
	};
}

function segment(
	name: string,
	x1: number,
	y1: number,
	x2: number,
	y2: number,
	stroke: Stroke
): Shape {
	return {
		...base(name),
		kind: 'line',
		x1: r2(x1),
		y1: r2(y1),
		x2: r2(x2),
		y2: r2(y2),
		stroke,
		start: 'none',
		end: 'none'
	};
}

/** A path shape, its points rounded the way the cleaner would. */
function figure(
	name: string,
	paths: Subpath[],
	fill: string | null,
	look: Look & { evenodd?: boolean } = {}
): Shape {
	return {
		...base(name, [...IDENTITY], look.opacity),
		kind: 'path',
		paths: paths.map((path) => ({
			closed: path.closed,
			anchors: path.anchors.map(
				(anchor) =>
					[
						r2(anchor[0]),
						r2(anchor[1]),
						r2(anchor[2]),
						r2(anchor[3]),
						r2(anchor[4]),
						r2(anchor[5]),
						anchor[6]
					] as Anchor
			)
		})),
		fillRule: look.evenodd ? 'evenodd' : 'nonzero',
		fill: fillOf(fill),
		stroke: look.stroke ?? null
	};
}

/** Shapes in a named group, or nothing if there are none. */
function group(name: string, children: Shape[]): Shape[] {
	return children.length ? [{ ...base(name), kind: 'group', children }] : [];
}

/** Turned by angle about the origin, then moved to (x, y). */
const turned = (angle: number, x: number, y: number): Matrix => [
	Math.cos(angle),
	Math.sin(angle),
	-Math.sin(angle),
	Math.cos(angle),
	x,
	y
];

// ---- Paths -------------------------------------------------------------------------------------

const point = (x: number, y: number): Anchor => [x, y, x, y, x, y, 0];

/** Builds subpaths a step at a time, the way SVG path data reads. */
class Trace {
	#paths: Subpath[] = [];
	#anchors: Anchor[] = [];

	move(x: number, y: number) {
		this.#end(false);
		this.#anchors = [point(x, y)];
		return this;
	}

	line(x: number, y: number) {
		this.#anchors.push(point(x, y));
		return this;
	}

	curve(c1x: number, c1y: number, c2x: number, c2y: number, x: number, y: number) {
		const last = this.#anchors[this.#anchors.length - 1];
		last[4] = c1x;
		last[5] = c1y;
		this.#anchors.push([x, y, c2x, c2y, x, y, 0]);
		return this;
	}

	/** Part of a circle, from the point now (which must be on it, at `from`), by `sweep`. */
	arc(cx: number, cy: number, radius: number, from: number, sweep: number) {
		const steps = Math.max(1, Math.ceil(Math.abs(sweep) / (Math.PI / 2) - 1e-9));
		const step = sweep / steps;
		const handle = (4 / 3) * Math.tan(step / 4) * radius;
		for (let index = 0; index < steps; index++) {
			const a0 = from + step * index;
			const a1 = a0 + step;
			const x0 = cx + Math.cos(a0) * radius;
			const y0 = cy + Math.sin(a0) * radius;
			const x1 = cx + Math.cos(a1) * radius;
			const y1 = cy + Math.sin(a1) * radius;
			this.curve(
				x0 - handle * Math.sin(a0),
				y0 + handle * Math.cos(a0),
				x1 + handle * Math.sin(a1),
				y1 - handle * Math.cos(a1),
				x1,
				y1
			);
		}
		return this;
	}

	close() {
		this.#end(true);
		return this;
	}

	done() {
		this.#end(false);
		return this.#paths;
	}

	#end(closed: boolean) {
		const anchors = this.#anchors;
		if (!anchors.length) return;
		this.#anchors = [];
		if (closed && anchors.length > 1) {
			// Ending where it began: the last point is the first, so they become one.
			const first = anchors[0];
			const last = anchors[anchors.length - 1];
			if (Math.abs(first[0] - last[0]) < 0.01 && Math.abs(first[1] - last[1]) < 0.01) {
				first[2] = last[2];
				first[3] = last[3];
				anchors.pop();
			}
		}
		for (const anchor of anchors) anchor[6] = smoothness(anchor);
		this.#paths.push({ closed, anchors });
	}
}

/** Smooth (1) when the point's handles are in a line, so the pen keeps the curve smooth. */
function smoothness(anchor: Anchor): 0 | 1 {
	const ix = anchor[2] - anchor[0];
	const iy = anchor[3] - anchor[1];
	const ox = anchor[4] - anchor[0];
	const oy = anchor[5] - anchor[1];
	const lengths = Math.hypot(ix, iy) * Math.hypot(ox, oy);
	if (lengths < 1e-6) return 0;
	return Math.abs(ix * oy - iy * ox) / lengths < 0.02 && ix * ox + iy * oy < 0 ? 1 : 0;
}

/** Paths moved through a matrix (a turn and a move). */
const placed = (paths: Subpath[], m: Matrix) => transformSubpaths(paths, m);

/**
 * A smooth line on through points, from the trace's point now (the first of them). The ends are
 * carried on straight, so evenly spaced points give curves whose x runs evenly too (`heightAt`).
 */
function through(trace: Trace, points: Point[]) {
	const at = extended(points);
	for (let index = 0; index < points.length - 1; index++) {
		const p0 = at(index - 1);
		const p1 = at(index);
		const p2 = at(index + 1);
		const p3 = at(index + 2);
		trace.curve(
			p1.x + (p2.x - p0.x) / 6,
			p1.y + (p2.y - p0.y) / 6,
			p2.x - (p3.x - p1.x) / 6,
			p2.y - (p3.y - p1.y) / 6,
			p2.x,
			p2.y
		);
	}
}

function extended(points: Point[]) {
	const n = points.length;
	return (index: number): Point => {
		if (index < 0) return { x: 2 * points[0].x - points[1].x, y: 2 * points[0].y - points[1].y };
		if (index >= n) {
			return {
				x: 2 * points[n - 1].x - points[n - 2].x,
				y: 2 * points[n - 1].y - points[n - 2].y
			};
		}
		return points[index];
	};
}

/** Where `through`'s line is at x, for points evenly spaced across. */
function heightAt(points: Point[], x: number, smooth: boolean) {
	const n = points.length;
	const step = (points[n - 1].x - points[0].x) / (n - 1);
	const index = Math.max(0, Math.min(n - 2, Math.floor((x - points[0].x) / step)));
	const t = Math.max(0, Math.min(1, (x - points[index].x) / step));
	if (!smooth) return points[index].y + (points[index + 1].y - points[index].y) * t;
	const at = extended(points);
	const y0 = at(index - 1).y;
	const y1 = at(index).y;
	const y2 = at(index + 1).y;
	const y3 = at(index + 2).y;
	const b1 = y1 + (y2 - y0) / 6;
	const b2 = y2 - (y3 - y1) / 6;
	const u = 1 - t;
	return u * u * u * y1 + 3 * u * u * t * b1 + 3 * u * t * t * b2 + t * t * t * y2;
}

/** A smooth closed shape through points. */
function loop(points: Point[]) {
	const n = points.length;
	const trace = new Trace().move(points[0].x, points[0].y);
	for (let index = 0; index < n; index++) {
		const p0 = points[(index - 1 + n) % n];
		const p1 = points[index];
		const p2 = points[(index + 1) % n];
		const p3 = points[(index + 2) % n];
		trace.curve(
			p1.x + (p2.x - p0.x) / 6,
			p1.y + (p2.y - p0.y) / 6,
			p2.x - (p3.x - p1.x) / 6,
			p2.y - (p3.y - p1.y) / 6,
			p2.x,
			p2.y
		);
	}
	return trace.close().done();
}

function polygonPath(points: Point[]) {
	const trace = new Trace().move(points[0].x, points[0].y);
	for (const item of points.slice(1)) trace.line(item.x, item.y);
	return trace.close().done();
}

const diamond = (name: string, x: number, y: number, radius: number, fill: string) =>
	figure(
		name,
		polygonPath([
			{ x, y: y - radius },
			{ x: x + radius, y },
			{ x, y: y + radius },
			{ x: x - radius, y }
		]),
		fill
	);

/** The sweep from one angle to another that passes the angle `via`. */
function sweepVia(from: number, to: number, via: number) {
	const ccw = (((to - from) % TURN) + TURN) % TURN;
	const at = (((via - from) % TURN) + TURN) % TURN;
	return at < ccw ? ccw : ccw - TURN;
}

/**
 * The part of a circle that a second one, moved by (dx, dy), doesn't cover: a crescent. A whole
 * circle when they don't meet.
 */
function crescent(cx: number, cy: number, radius: number, dx: number, dy: number, cut: number) {
	const d = Math.hypot(dx, dy);
	if (d >= radius + cut || d <= Math.abs(radius - cut)) {
		return new Trace()
			.move(cx + radius, cy)
			.arc(cx, cy, radius, 0, TURN)
			.close()
			.done();
	}
	// Where the two circles cross.
	const reach = (radius * radius - cut * cut + d * d) / (2 * d);
	const half = Math.sqrt(Math.max(0, radius * radius - reach * reach));
	const ux = dx / d;
	const uy = dy / d;
	const mx = cx + ux * reach;
	const my = cy + uy * reach;
	const first = { x: mx - uy * half, y: my + ux * half };
	const second = { x: mx + uy * half, y: my - ux * half };
	const away = Math.atan2(-uy, -ux);
	const bx = cx + dx;
	const by = cy + dy;
	const a1 = Math.atan2(first.y - cy, first.x - cx);
	const a2 = Math.atan2(second.y - cy, second.x - cx);
	const b2 = Math.atan2(second.y - by, second.x - bx);
	const b1 = Math.atan2(first.y - by, first.x - bx);
	return new Trace()
		.move(first.x, first.y)
		.arc(cx, cy, radius, a1, sweepVia(a1, a2, away))
		.arc(bx, by, cut, b2, sweepVia(b2, b1, away))
		.close()
		.done();
}

/** A pointed leaf shape along x, from `from` to `to`, `belly` its curve's reach either side. */
function lens(from: number, to: number, belly: number) {
	const quarter = (to - from) / 4;
	return new Trace()
		.move(from, 0)
		.curve(from + quarter, -belly, to - quarter, -belly, to, 0)
		.curve(to - quarter, belly, from + quarter, belly, from, 0)
		.close()
		.done();
}

// ---- Ridges of land ----------------------------------------------------------------------------

type Ridge = { points: Point[]; smooth: boolean };

/** Heights from -1 to 1 by midpoint displacement: the jagged line of mountains. */
function displaced(roll: Roll, count: number, roughness: number) {
	let values = [roll.range(-1, 1), roll.range(-1, 1)];
	let spread = 1;
	while (values.length < count) {
		const next: number[] = [];
		for (let index = 0; index < values.length - 1; index++) {
			next.push(
				values[index],
				(values[index] + values[index + 1]) / 2 + roll.range(-spread, spread)
			);
		}
		next.push(values[values.length - 1]);
		values = next;
		spread *= roughness;
	}
	const most = Math.max(...values.map(Math.abs)) || 1;
	return values.map((value) => value / most);
}

/** A line of land across the drawing, rising from `lowest` by up to `rise`. */
function makeRidge(roll: Roll, width: number, lowest: number, rise: number, jagged: boolean) {
	const count = jagged ? 33 : roll.int(5, 8);
	const heights = jagged
		? displaced(roll, count, roll.range(0.45, 0.6))
		: Array.from({ length: count }, () => roll.range(-1, 1));
	const points = heights.map((value, index) => ({
		x: -width * 0.05 + (width * 1.1 * index) / (count - 1),
		y: lowest - ((value + 1) / 2) * rise
	}));
	return { points, smooth: !jagged } satisfies Ridge;
}

function ridgeFigure(name: string, ridge: Ridge, bottom: number, fill: string) {
	const { points } = ridge;
	const trace = new Trace().move(points[0].x, bottom).line(points[0].x, points[0].y);
	if (ridge.smooth) through(trace, points);
	else for (const item of points.slice(1)) trace.line(item.x, item.y);
	trace.line(points[points.length - 1].x, bottom);
	return figure(name, trace.close().done(), fill);
}

/** A pine tree standing at (x, y), in tiers. */
function pine(x: number, y: number, tall: number) {
	const right = [
		[0, -1],
		[0.13, -0.62],
		[0.06, -0.62],
		[0.19, -0.28],
		[0.09, -0.28],
		[0.24, 0.12]
	];
	const left = right
		.slice(1)
		.reverse()
		.map(([dx, dy]) => [-dx, dy]);
	return polygonPath(
		[...right, ...left].map(([dx, dy]) => ({ x: x + dx * tall, y: y + dy * tall }))
	);
}

/** How many of something to scatter: so many for each square of the drawing, up to `most`. */
const scatter = (width: number, height: number, perSquare: number, most: number) =>
	Math.round(Math.min(most, ((width * height) / Math.min(width, height) ** 2) * perSquare));

/**
 * Bands of one colour laid over each other, more of them towards `horizon`: a sky's glow, until
 * the studio has gradients. Many faint bands, so no step shows.
 */
function glow(name: string, width: number, height: number, horizon: number, color: string) {
	const bands: Shape[] = [];
	const count = 18;
	for (let band = 1; band <= count; band++) {
		const top = horizon * (1 - (band / count) * 0.92);
		bands.push(rect(name, 0, top, width, height - top, color, { opacity: 0.036 }));
	}
	return bands;
}

// ---- The kinds ---------------------------------------------------------------------------------

type Maker = (roll: Roll, width: number, height: number) => Shape[];

const nightSky: Maker = (roll, width, height) => {
	const tones = paletteOf(roll);
	const s = Math.min(width, height);
	const sky = mix(tones[0], '#02030cff', 0.45);
	const haze = roll.pick([tones[1], tones[2]]);
	const light = mix(WHITE, tones[4], 0.25);
	const water = roll.chance(0.4);
	const horizon = height * (water ? roll.range(0.58, 0.7) : roll.range(0.66, 0.8));

	const air = [
		rect('Night', 0, 0, width, height, sky),
		...glow('Glow', width, height, horizon, haze)
	];

	const stars: Shape[] = [];
	const count = scatter(width, height, roll.range(70, 120), 450);
	for (let index = 0; index < count; index++) {
		const big = roll.chance(0.08);
		stars.push(
			circle(
				'Star',
				roll.range(0, width),
				horizon * roll.next() ** 1.4,
				s * roll.range(0.0012, 0.0032) * (big ? 1.9 : 1),
				light,
				{ opacity: roll.range(0.35, 1) }
			)
		);
	}
	for (let index = roll.int(3, 6); index > 0; index--) {
		const x = width * roll.range(0.05, 0.95);
		const y = horizon * roll.range(0.05, 0.7);
		const radius = s * roll.range(0.009, 0.017);
		stars.push(circle('Glow', x, y, radius * 1.3, light, { opacity: 0.12 }));
		stars.push(star('Bright star', x, y, radius, 4, 0.16, light));
	}

	const moonRadius = s * roll.range(0.055, 0.095);
	const mx = width * roll.range(0.22, 0.78);
	const my = horizon * roll.range(0.22, 0.5);
	const pale = mix('#fbf3dcff', tones[4], 0.2);
	const moon = [3, 2.1, 1.5].map((size) =>
		circle('Halo', mx, my, moonRadius * size, pale, { opacity: 0.05 })
	);
	if (roll.chance(0.65)) {
		// The dark of the moon, faintly lit, then its crescent.
		const angle = roll.range(-0.8, 0.8) + (roll.chance(0.5) ? Math.PI : 0);
		const shift = moonRadius * roll.range(0.3, 0.55);
		moon.push(circle('Dark side', mx, my, moonRadius, mix(sky, pale, 0.08)));
		moon.push(
			figure(
				'Moon',
				crescent(mx, my, moonRadius, Math.cos(angle) * shift, Math.sin(angle) * shift, moonRadius),
				pale
			)
		);
	} else {
		moon.push(circle('Moon', mx, my, moonRadius, pale));
		const seas = mix(pale, tones[2], 0.3);
		for (let index = roll.int(3, 5); index > 0; index--) {
			const angle = roll.range(0, TURN);
			const distance = moonRadius * roll.range(0.1, 0.55);
			moon.push(
				circle(
					'Sea',
					mx + Math.cos(angle) * distance,
					my + Math.sin(angle) * distance,
					moonRadius * roll.range(0.1, 0.26),
					seas,
					{ opacity: 0.4 }
				)
			);
		}
	}

	const sea: Shape[] = [];
	if (water) {
		const tone = mix(sky, haze, 0.28);
		const below = height - horizon;
		sea.push(rect('Water', 0, horizon, width, below, tone));
		for (let index = roll.int(5, 9); index > 0; index--) {
			sea.push(
				rect(
					'Ripple',
					width * roll.range(-0.1, 0.9),
					horizon + below * roll.range(0.08, 0.95),
					width * roll.range(0.1, 0.35),
					s * 0.003,
					mix(tone, haze, 0.6),
					{ radius: s * 0.0015, opacity: 0.5 }
				)
			);
		}
		// The moon's light on the water, breaking up towards the shore.
		const glints = roll.int(9, 14);
		for (let index = 0; index < glints; index++) {
			const t = index / glints;
			const half = moonRadius * (1 - 0.55 * t) * roll.range(0.5, 1.2);
			const thick = s * 0.005 * (1 + t * 1.5);
			sea.push(
				rect(
					'Glint',
					mx - half + moonRadius * roll.range(-0.25, 0.25),
					horizon + below * (0.03 + 0.9 * t ** 1.3),
					half * 2,
					thick,
					pale,
					{ radius: thick / 2, opacity: 0.6 - 0.4 * t }
				)
			);
		}
	}

	const land: Shape[] = [];
	const ridges = water ? 1 : roll.int(2, 3);
	const far = mix(mix(sky, haze, 0.35), BLACK, 0.1);
	const near = mix(sky, BLACK, 0.45);
	for (let index = 0; index < ridges; index++) {
		const t = ridges === 1 ? 0 : index / (ridges - 1);
		const lowest = water ? horizon + 1 : horizon + s * 0.03 + (height - horizon) * 0.45 * t;
		const rise = s * (water ? roll.range(0.02, 0.045) : roll.range(0.07, 0.13) * (1 - 0.4 * t));
		const ridge = makeRidge(roll, width, lowest, rise, index === 0 && roll.chance(0.6));
		land.push(
			ridgeFigure(
				index === 0 ? 'Far hills' : 'Hills',
				ridge,
				water ? horizon + 1 : height + 2,
				mix(far, near, water ? 0.4 : t)
			)
		);
	}

	return [
		...group('Sky', air),
		...group('Stars', stars),
		...group('Moon', moon),
		...group('Water', sea),
		...group('Land', land)
	];
};

const mountains: Maker = (roll, width, height) => {
	const tones = paletteOf(roll);
	const s = Math.min(width, height);
	const dusk = roll.chance(0.35);
	const sky = dusk ? mix(tones[1], tones[0], 0.35) : mix(tones[4], tones[3], roll.range(0.05, 0.4));
	const haze = dusk ? mix(tones[3], tones[4], 0.3) : mix(tones[4], WHITE, 0.5);
	const horizon = height * roll.range(0.42, 0.58);

	const air = [
		rect('Sky', 0, 0, width, height, sky),
		...glow('Haze', width, height, horizon, haze)
	];

	const sunRadius = s * roll.range(0.06, 0.12);
	const sx = width * roll.range(0.2, 0.8);
	const sy = horizon - s * roll.range(0.02, 0.25);
	const sunColor = dusk ? mix(tones[4], '#ffd9a0ff', 0.4) : mix(accent(tones), WHITE, 0.2);
	const sun = [2.4, 1.6].map((size) =>
		circle('Glow', sx, sy, sunRadius * size, sunColor, { opacity: 0.1 })
	);
	sun.push(circle('Sun', sx, sy, sunRadius, sunColor));

	const birds: Shape[] = [];
	if (roll.chance(0.5)) {
		const color = mix(tones[0], sky, 0.25);
		const bx = width * roll.range(0.2, 0.8);
		const by = horizon * roll.range(0.2, 0.55);
		for (let index = roll.int(3, 7); index > 0; index--) {
			const x = bx + s * roll.range(-0.15, 0.15);
			const y = by + s * roll.range(-0.08, 0.08);
			const span = s * roll.range(0.012, 0.024);
			const lift = span * roll.range(0.3, 0.6);
			const wings = new Trace()
				.move(x - span, y - lift * 0.4)
				.curve(x - span * 0.6, y - lift, x - span * 0.2, y - lift * 0.8, x, y)
				.curve(x + span * 0.2, y - lift * 0.8, x + span * 0.6, y - lift, x + span, y - lift * 0.4)
				.done();
			birds.push(figure('Bird', wings, null, { stroke: strokeOf(color, span * 0.16) }));
		}
	}

	const land: Shape[] = [];
	const count = roll.int(4, 6);
	const far = mix(sky, tones[2], 0.4);
	const near = mix(tones[0], tones[1], 0.25);
	let front: { ridge: Ridge; color: string } | null = null;
	for (let index = 0; index < count; index++) {
		const t = index / (count - 1);
		const color = mix(far, near, t ** 0.85);
		const lowest = horizon + (height - horizon) * (0.06 + 0.72 * t);
		const rise = s * (0.22 - 0.15 * t) * roll.range(0.75, 1.15);
		const ridge = makeRidge(roll, width, lowest, rise, t < 0.5);
		if (index > 0 && roll.chance(0.55)) {
			// Mist in the valley, in front of the ridge behind.
			land.push(
				rect(
					'Mist',
					-width * 0.1,
					lowest - rise * 0.55,
					width * 1.2,
					s * roll.range(0.03, 0.07),
					haze,
					{ radius: s * 0.035, opacity: 0.3 }
				)
			);
		}
		land.push(ridgeFigure(t < 0.5 ? 'Mountains' : 'Hills', ridge, height + 2, color));
		front = { ridge, color };
	}

	const trees: Shape[] = [];
	if (front && roll.chance(0.55)) {
		for (let index = roll.int(6, 22); index > 0; index--) {
			const x = roll.range(0, width);
			const y = heightAt(front.ridge.points, x, front.ridge.smooth);
			trees.push(figure('Pine', pine(x, y, s * roll.range(0.035, 0.085)), front.color));
		}
	}

	return [
		...group('Sky', air),
		...group('Sun', sun),
		...group('Birds', birds),
		...group('Land', land),
		...group('Pines', trees)
	];
};

const waves: Maker = (roll, width, height) => {
	const tones = paletteOf(roll);
	const s = Math.min(width, height);
	const lightFirst = roll.chance(0.6);
	const order = lightFirst ? [...tones].reverse() : tones;
	const sky = lightFirst ? mix(order[0], WHITE, 0.15) : mix(order[0], '#02030cff', 0.2);
	const top = height * roll.range(0.28, 0.45);

	const shapes: Shape[] = [rect('Sky', 0, 0, width, height, sky)];
	if (roll.chance(0.75)) {
		const radius = s * roll.range(0.1, 0.2);
		shapes.push(
			circle(
				'Sun',
				width * roll.range(0.25, 0.75),
				top - radius * roll.range(-0.2, 0.6),
				radius,
				mix(accent(tones), sky, 0.1)
			)
		);
	}

	const count = roll.int(6, 11);
	const cycles = roll.range(1.2, 3.2);
	const crests = roll.chance(0.6);
	const samples = 48;
	for (let index = 0; index < count; index++) {
		const t = index / (count - 1);
		const lowest = top + (height - top) * (index / count) ** 0.9;
		const amplitude = s * roll.range(0.012, 0.035) * (0.7 + t * 0.8);
		const phase = roll.range(0, TURN);
		const wobble = roll.range(0, TURN);
		const points = Array.from({ length: samples + 1 }, (_, step) => {
			const x = -width * 0.05 + (width * 1.1 * step) / samples;
			const u = x / width;
			return {
				x,
				y:
					lowest +
					amplitude * Math.sin(TURN * cycles * u + phase) +
					amplitude * 0.35 * Math.sin(TURN * cycles * 2.3 * u + wobble)
			};
		});
		const color = along(order, 0.18 + 0.82 * t);
		const body = new Trace().move(points[0].x, height + 2).line(points[0].x, points[0].y);
		through(body, points);
		body.line(points[samples].x, height + 2);
		const band = [figure('Wave', body.close().done(), color)];
		if (crests) {
			const lower = points.map((item) => ({ x: item.x, y: item.y + s * 0.009 }));
			const crest = new Trace().move(lower[0].x, lower[0].y);
			through(crest, lower);
			band.push(
				figure('Crest', crest.done(), null, {
					stroke: strokeOf(mix(color, order[0], 0.45), s * 0.004),
					opacity: 0.7
				})
			);
		}
		shapes.push(...(band.length > 1 ? group('Wave', band) : band));
	}
	return shapes;
};

const MOTIFS = [
	'quarter',
	'half',
	'circle',
	'ring',
	'triangle',
	'diamond',
	'stripes',
	'dots',
	'leaf',
	'square',
	'cross'
] as const;
type Motif = (typeof MOTIFS)[number] | 'plain';

function motif(
	kind: Motif,
	roll: Roll,
	x: number,
	y: number,
	w: number,
	front: string,
	third: string
): Shape[] {
	const turn = roll.int(0, 3);
	const corners = [
		[x, y],
		[x + w, y],
		[x + w, y + w],
		[x, y + w]
	];
	const mx = x + w / 2;
	const my = y + w / 2;
	switch (kind) {
		case 'quarter': {
			const [cx, cy] = corners[turn];
			const from = (turn * Math.PI) / 2;
			const quarter = (radius: number) =>
				new Trace()
					.move(cx, cy)
					.line(cx + Math.cos(from) * radius, cy + Math.sin(from) * radius)
					.arc(cx, cy, radius, from, Math.PI / 2)
					.close()
					.done();
			const shapes = [figure('Quarter circle', quarter(w), front)];
			if (roll.chance(0.3)) shapes.push(figure('Quarter circle', quarter(w * 0.5), third));
			return shapes;
		}
		case 'half': {
			const centres = [
				[mx, y],
				[x + w, my],
				[mx, y + w],
				[x, my]
			];
			const half = (at: number, color: string) => {
				const [cx, cy] = centres[at];
				const from = (at * Math.PI) / 2;
				const path = new Trace()
					.move(cx + (Math.cos(from) * w) / 2, cy + (Math.sin(from) * w) / 2)
					.arc(cx, cy, w / 2, from, Math.PI)
					.close()
					.done();
				return figure('Half circle', path, color);
			};
			return roll.chance(0.35)
				? [half(turn, front), half((turn + 2) % 4, third)]
				: [half(turn, front)];
		}
		case 'circle':
			return [
				circle('Circle', mx, my, w * 0.36, front),
				...(roll.chance(0.35) ? [circle('Circle', mx, my, w * 0.16, third)] : [])
			];
		case 'ring':
			return [
				circle('Ring', mx, my, w * 0.3, null, { stroke: strokeOf(front, w * 0.1) }),
				...(roll.chance(0.5) ? [circle('Dot', mx, my, w * 0.09, third)] : [])
			];
		case 'triangle':
			return [
				figure(
					'Triangle',
					polygonPath(
						[0, 1, 2]
							.map((step) => corners[(turn + step) % 4])
							.map(([px, py]) => ({ x: px, y: py }))
					),
					front
				)
			];
		case 'diamond':
			return [
				diamond('Diamond', mx, my, w / 2, front),
				...(roll.chance(0.4) ? [diamond('Diamond', mx, my, w / 4, third)] : [])
			];
		case 'stripes': {
			const count = roll.pick([3, 4, 5]);
			const band = w / count;
			const across = turn % 2 === 0;
			return Array.from({ length: count }, (_, step) =>
				across
					? rect('Stripe', x, y + band * (step + 0.25), w, band * 0.5, front)
					: rect('Stripe', x + band * (step + 0.25), y, band * 0.5, w, front)
			);
		}
		case 'dots': {
			const grid = roll.pick([2, 3, 4]);
			const step = w / grid;
			const dots: Shape[] = [];
			for (let row = 0; row < grid; row++) {
				for (let column = 0; column < grid; column++) {
					dots.push(
						circle('Dot', x + step * (column + 0.5), y + step * (row + 0.5), step * 0.24, front)
					);
				}
			}
			return dots;
		}
		case 'leaf': {
			// Two quarter circles between opposite corners.
			const path =
				turn % 2 === 0
					? new Trace()
							.move(x, y)
							.arc(x, y + w, w, -Math.PI / 2, Math.PI / 2)
							.arc(x + w, y, w, Math.PI / 2, Math.PI / 2)
							.close()
							.done()
					: new Trace()
							.move(x + w, y)
							.arc(x, y, w, 0, Math.PI / 2)
							.arc(x + w, y + w, w, Math.PI, Math.PI / 2)
							.close()
							.done();
			return [figure('Leaf', path, front)];
		}
		case 'square':
			return [
				rect('Square', x + w * 0.25, y + w * 0.25, w * 0.5, w * 0.5, front, {
					angle: roll.chance(0.3) ? Math.PI / 4 : 0
				})
			];
		case 'cross': {
			const bar = w * 0.2;
			const long = w * 0.64;
			const angle = roll.chance(0.3) ? Math.PI / 4 : 0;
			return [
				rect('Bar', mx - long / 2, my - bar / 2, long, bar, front, { angle }),
				rect('Bar', mx - bar / 2, my - long / 2, bar, long, front, { angle })
			];
		}
		case 'plain':
			return [];
	}
}

const tiles: Maker = (roll, width, height) => {
	const colors = roll.shuffle(paletteOf(roll));
	const s = Math.min(width, height);
	// About 150 tiles at most, however long and thin the drawing.
	const cell = Math.max(s / roll.int(3, 6), Math.sqrt((width * height) / 150));
	const columns = Math.max(2, Math.round(width / cell));
	const size = width / columns;
	const rows = Math.ceil(height / size - 0.01);
	const top = (height - rows * size) / 2;
	const ground = colors[0];
	const shapes: Shape[] = [rect('Ground', 0, 0, width, height, ground)];

	if (roll.chance(0.22)) {
		// Truchet tiles: two quarter circles in each, turned either way, so the lines run on from
		// tile to tile.
		const stroke = strokeOf(colors[1], size * roll.range(0.12, 0.2), { cap: 'butt' });
		for (let row = 0; row < rows; row++) {
			for (let column = 0; column < columns; column++) {
				const x = column * size;
				const y = top + row * size;
				const r = size / 2;
				const arcs = roll.chance(0.5)
					? new Trace()
							.move(x + r, y)
							.arc(x, y, r, 0, Math.PI / 2)
							.move(x + r, y + size)
							.arc(x + size, y + size, r, Math.PI, Math.PI / 2)
							.done()
					: new Trace()
							.move(x + size, y + r)
							.arc(x + size, y, r, Math.PI / 2, Math.PI / 2)
							.move(x, y + r)
							.arc(x, y + size, r, -Math.PI / 2, Math.PI / 2)
							.done();
				shapes.push(figure('Tile', arcs, null, { stroke }));
			}
		}
		return shapes;
	}

	const gap = roll.chance(0.3) ? size * roll.range(0.04, 0.07) : 0;
	const vocabulary: Motif[] = roll.shuffle(MOTIFS).slice(0, roll.int(3, 5));
	for (let row = 0; row < rows; row++) {
		for (let column = 0; column < columns; column++) {
			const x = column * size + gap / 2;
			const y = top + row * size + gap / 2;
			const w = size - gap;
			const back = roll.pick(gap ? colors.filter((color) => color !== ground) : colors);
			const front = roll.pick(colors.filter((color) => color !== back));
			const third = roll.pick(colors.filter((color) => color !== back && color !== front));
			const kind: Motif = roll.chance(0.08) ? 'plain' : roll.pick(vocabulary);
			shapes.push(
				...group('Tile', [
					rect('Square', x, y, w, w, back),
					...motif(kind, roll, x, y, w, front, third)
				])
			);
		}
	}
	return shapes;
};

function leaf(
	roll: Roll,
	x: number,
	y: number,
	length: number,
	color: string,
	vein: string | null
) {
	const m = turned(roll.range(0, TURN), x, y);
	const belly = length * roll.range(0.22, 0.34);
	const body = figure('Leaf', placed(lens(-length / 2, length / 2, belly), m), color);
	if (!vein) return [body];
	const rib = new Trace()
		.move(-length * 0.42, 0)
		.curve(-length * 0.15, -belly * 0.12, length * 0.15, -belly * 0.12, length * 0.4, 0)
		.done();
	return group('Leaf', [
		body,
		figure('Vein', placed(rib, m), null, { stroke: strokeOf(vein, length * 0.018) })
	]);
}

/**
 * A seaweed frond standing on (x, y), leaning by `lean`: a long shape whose edges swell into
 * lobes, the left side's between the right's.
 */
function frond(roll: Roll, x: number, y: number, length: number, lean: number) {
	const width = length * roll.range(0.12, 0.2);
	const lobes = roll.int(2, 4);
	const bend = roll.range(-0.25, 0.25);
	const steps = 18;
	const side = (t: number, way: -1 | 1) => {
		const swell = Math.sin(Math.PI * t) ** 0.8;
		const lobe = 0.68 + 0.32 * Math.cos(lobes * TURN * t + (way > 0 ? Math.PI : 0));
		return { x: bend * length * t * t + way * width * swell * lobe, y: -length * t };
	};
	const points: Point[] = [];
	for (let step = 0; step <= steps; step++) points.push(side(step / steps, -1));
	for (let step = steps - 1; step > 0; step--) points.push(side(step / steps, 1));
	return placed(loop(points), turned(lean, x, y));
}

const cutouts: Maker = (roll, width, height) => {
	const tones = paletteOf(roll);
	const s = Math.min(width, height);
	const light = roll.chance(0.7);
	const ground = light ? mix(tones[4], WHITE, 0.25) : mix(tones[0], BLACK, 0.15);
	const inks = light ? tones.slice(0, 4) : tones.slice(1);
	const spread = Math.min(2.5, Math.sqrt((width * height) / (s * s)));
	const spot = () => ({ x: width * roll.range(0.08, 0.92), y: height * roll.range(0.08, 0.92) });

	const shapes: Shape[] = [rect('Paper', 0, 0, width, height, ground)];
	if (roll.chance(0.4)) {
		// A big round sun, part off the edge.
		const radius = s * roll.range(0.18, 0.3);
		shapes.push(
			circle(
				'Sun',
				roll.pick([0.15, 0.85]) * width,
				roll.range(0.1, 0.35) * height,
				radius,
				roll.pick(inks)
			)
		);
	}
	// Big soft shapes to lay the rest on, kept apart so they don't pile up.
	const masses: { x: number; y: number; radius: number }[] = [];
	const clear = (centre: Point, radius: number) =>
		masses.every(
			(other) => Math.hypot(other.x - centre.x, other.y - centre.y) > (other.radius + radius) * 0.85
		);
	for (let index = Math.round(roll.int(2, 4) * spread); index > 0; index--) {
		const radius = s * roll.range(0.1, 0.2);
		let centre = spot();
		for (let tries = 0; tries < 30 && !clear(centre, radius); tries++) centre = spot();
		masses.push({ ...centre, radius });
		const corners = roll.int(5, 8);
		const points = Array.from({ length: corners }, (_, step) => {
			const angle = (step / corners) * TURN + roll.range(-0.25, 0.25) * (TURN / corners);
			const reach = radius * roll.range(0.72, 1.25);
			return { x: centre.x + Math.cos(angle) * reach, y: centre.y + Math.sin(angle) * reach };
		});
		shapes.push(figure('Shape', loop(points), roll.pick(inks)));
	}
	// Fronds rising from the foot of the page.
	for (let index = Math.round(roll.int(2, 4) * spread); index > 0; index--) {
		shapes.push(
			figure(
				'Frond',
				frond(
					roll,
					width * roll.range(0.05, 0.95),
					height + s * 0.02,
					height * roll.range(0.3, 0.6),
					roll.range(-0.35, 0.35)
				),
				roll.pick(inks)
			)
		);
	}

	const pieces: Shape[] = [];
	for (let index = Math.round(roll.int(3, 7) * spread); index > 0; index--) {
		const where = spot();
		const color = roll.pick(inks);
		const vein = roll.chance(0.5)
			? roll.pick([ground, ...inks.filter((ink) => ink !== color)])
			: null;
		pieces.push(...leaf(roll, where.x, where.y, s * roll.range(0.12, 0.26), color, vein));
	}
	if (roll.chance(0.5)) {
		for (let index = roll.int(2, 5); index > 0; index--) {
			const where = spot();
			pieces.push(
				star(
					'Star',
					where.x,
					where.y,
					s * roll.range(0.025, 0.06),
					roll.pick([5, 6, 8]),
					roll.range(0.35, 0.5),
					roll.pick(inks),
					{ angle: roll.range(0, TURN) }
				)
			);
		}
	}
	for (let index = roll.int(1, 3); index > 0; index--) {
		const start = spot();
		const angle = roll.range(0, TURN);
		const length = s * roll.range(0.2, 0.4);
		const sway = s * roll.range(0.015, 0.035);
		const points = Array.from({ length: 6 }, (_, step) => {
			const forward = (step / 5) * length;
			const aside = (step % 2 ? 1 : -1) * sway;
			return {
				x: start.x + Math.cos(angle) * forward - Math.sin(angle) * aside,
				y: start.y + Math.sin(angle) * forward + Math.cos(angle) * aside
			};
		});
		const trace = new Trace().move(points[0].x, points[0].y);
		through(trace, points);
		pieces.push(
			figure('Line', trace.done(), null, {
				stroke: strokeOf(roll.pick(inks), s * roll.range(0.006, 0.012))
			})
		);
	}
	shapes.push(...roll.shuffle(pieces));

	const dots: Shape[] = [];
	for (let index = Math.round(roll.int(8, 20) * spread); index > 0; index--) {
		const where = spot();
		dots.push(circle('Dot', where.x, where.y, s * roll.range(0.008, 0.02), roll.pick(inks)));
	}
	shapes.push(...group('Dots', dots));
	return shapes;
};

function planet(
	roll: Roll,
	x: number,
	y: number,
	radius: number,
	color: string,
	sun: Point,
	space: string,
	light: string,
	tilt: number
): Shape[] {
	const parts: Shape[] = [];
	const ringed = roll.chance(0.3);
	const angle = tilt + roll.range(-0.35, 0.35);
	const rx = radius * 2.1;
	const ry = radius * roll.range(0.35, 0.6);
	const ringColor = mix(color, light, 0.35);
	// Half a ring at a time, so the back half goes behind the planet and the front half before it.
	const halfRing = (from: number) =>
		figure(
			'Ring',
			placed(
				new Trace()
					.move(Math.cos(from) * 100, Math.sin(from) * 100)
					.arc(0, 0, 100, from, Math.PI)
					.done(),
				[
					(rx / 100) * Math.cos(angle),
					(rx / 100) * Math.sin(angle),
					(-ry / 100) * Math.sin(angle),
					(ry / 100) * Math.cos(angle),
					x,
					y
				]
			),
			null,
			{ stroke: strokeOf(ringColor, radius * 0.16, { cap: 'butt' }) }
		);
	if (ringed) parts.push(halfRing(Math.PI));
	parts.push(circle('Planet', x, y, radius, color));
	const dx = sun.x - x;
	const dy = sun.y - y;
	const d = Math.hypot(dx, dy) || 1;
	const shift = radius * 0.55;
	parts.push(
		figure(
			'Shadow',
			crescent(x, y, radius, (dx / d) * shift, (dy / d) * shift, radius * 1.02),
			space,
			{
				opacity: 0.55
			}
		)
	);
	if (ringed) parts.push(halfRing(0));
	if (roll.chance(0.3)) {
		const around = roll.range(0, TURN);
		const distance = radius * roll.range(1.9, 2.6);
		parts.push(
			circle(
				'Moon',
				x + Math.cos(around) * distance,
				y + Math.sin(around) * distance,
				radius * roll.range(0.18, 0.3),
				mix(light, color, 0.3)
			)
		);
	}
	return group('Planet', parts);
}

const orbits: Maker = (roll, width, height) => {
	const tones = paletteOf(roll);
	const s = Math.min(width, height);
	const space = mix(tones[0], '#02030aff', 0.5);
	const light = mix(WHITE, tones[4], 0.3);

	const backdrop: Shape[] = [rect('Space', 0, 0, width, height, space)];
	const count = scatter(width, height, roll.range(60, 110), 400);
	for (let index = 0; index < count; index++) {
		backdrop.push(
			circle(
				'Star',
				roll.range(0, width),
				roll.range(0, height),
				s * roll.range(0.001, 0.003),
				light,
				{ opacity: roll.range(0.25, 0.85) }
			)
		);
	}

	const sun = { x: width * roll.range(0.3, 0.7), y: height * roll.range(0.3, 0.7) };
	const squash = roll.range(0.3, 0.85);
	const tilt = roll.range(-0.4, 0.4);
	const sunRadius = s * roll.range(0.045, 0.08);
	const sunColor = mix(accent(tones), '#fff4d6ff', 0.3);
	const shining = [3.4, 2.3, 1.55].map((size) =>
		circle('Glow', sun.x, sun.y, sunRadius * size, sunColor, { opacity: 0.07 })
	);
	shining.push(circle('Sun', sun.x, sun.y, sunRadius, sunColor));

	const rings: Shape[] = [];
	const planets: Shape[] = [];
	const ringStroke = strokeOf(tint(light, 0.32), s * 0.0022, {
		dash: roll.chance(0.3) ? [2, 3] : []
	});
	const most = Math.hypot(width, height) * 0.6;
	let radius = sunRadius * roll.range(2.2, 3);
	for (let index = 0; index < 7 && radius < most; index++) {
		rings.push(
			ellipse('Orbit', sun.x, sun.y, radius, radius * squash, null, {
				stroke: ringStroke,
				angle: tilt
			})
		);
		const theta = roll.range(0, TURN);
		const x =
			sun.x +
			radius * Math.cos(theta) * Math.cos(tilt) -
			radius * squash * Math.sin(theta) * Math.sin(tilt);
		const y =
			sun.y +
			radius * Math.cos(theta) * Math.sin(tilt) +
			radius * squash * Math.sin(theta) * Math.cos(tilt);
		planets.push(
			...planet(
				roll,
				x,
				y,
				s * roll.range(0.012, 0.038),
				roll.pick(tones.slice(1)),
				sun,
				space,
				light,
				tilt
			)
		);
		radius *= roll.range(1.28, 1.6);
	}

	const comet: Shape[] = [];
	if (roll.chance(0.35)) {
		const hx = width * roll.range(0.1, 0.9);
		const hy = height * roll.range(0.1, 0.9);
		const d = Math.hypot(hx - sun.x, hy - sun.y) || 1;
		// The tail points away from the sun.
		const ux = (hx - sun.x) / d;
		const uy = (hy - sun.y) / d;
		const head = s * roll.range(0.006, 0.011);
		const length = s * roll.range(0.12, 0.25);
		const tail = polygonPath([
			{ x: hx - uy * head, y: hy + ux * head },
			{ x: hx + ux * length, y: hy + uy * length },
			{ x: hx + uy * head, y: hy - ux * head }
		]);
		comet.push(
			figure('Tail', tail, light, { opacity: 0.3 }),
			circle('Glow', hx, hy, head * 2.2, light, { opacity: 0.15 }),
			circle('Head', hx, hy, head, light)
		);
	}

	return [
		...group('Space', backdrop),
		...group('Orbits', rings),
		...group('Sun', shining),
		...planets,
		...group('Comet', comet)
	];
};

const rosette: Maker = (roll, width, height) => {
	const tones = paletteOf(roll);
	const s = Math.min(width, height);
	const dark = roll.chance(0.6);
	const ground = dark ? mix(tones[0], BLACK, 0.1) : mix(tones[4], WHITE, 0.2);
	const inks = roll.shuffle(dark ? tones.slice(1) : tones.slice(0, 4));
	const cx = width / 2;
	const cy = height / 2;
	const wide = width / height > 1.8;
	const tall = height / width > 1.3;
	const radius = s * (wide ? 0.42 : 0.36);
	const folds = roll.pick([6, 8, 8, 10, 12, 12, 16]);
	const spin = roll.chance(0.5) ? 0 : Math.PI / folds;
	const angleOf = (index: number, offset = 0) =>
		-Math.PI / 2 + spin + offset + (index / folds) * TURN;

	const flower: Shape[] = [];
	for (let index = 0; index < folds * 2; index++) {
		const angle = angleOf(index / 2);
		flower.push(
			circle(
				'Dot',
				cx + Math.cos(angle) * radius * 0.97,
				cy + Math.sin(angle) * radius * 0.97,
				radius * 0.032,
				inks[2]
			)
		);
	}
	const belly = ((radius * 1.9) / folds) * roll.range(0.85, 1.1);
	const petals = (
		name: string,
		from: number,
		to: number,
		reach: number,
		offset: number,
		color: string
	) => {
		for (let index = 0; index < folds; index++) {
			const m = turned(angleOf(index, offset), cx, cy);
			flower.push(figure(name, placed(lens(radius * from, radius * to, reach), m), color));
		}
	};
	petals('Petal', 0.2, 0.88, belly, 0, inks[0]);
	petals('Small petal', 0.18, 0.62, belly * 0.7, Math.PI / folds, inks[1]);
	if (roll.chance(0.5))
		petals('Inner petal', 0.32, 0.72, belly * 0.4, 0, mix(ground, inks[0], 0.25));
	flower.push(
		circle('Ring', cx, cy, radius * 0.24, null, { stroke: strokeOf(inks[2], radius * 0.022) }),
		star('Star', cx, cy, radius * 0.19, folds, 0.55, inks[3 % inks.length], { angle: spin }),
		circle('Centre', cx, cy, radius * 0.065, inks[0])
	);

	const border: Shape[] = [];
	if (wide) {
		// Rules running out to either side, as for a scene break.
		const margin = height * 0.12;
		const thick = radius * 0.028;
		for (const way of [-1, 1]) {
			const from = cx + way * radius * 1.08;
			const to = way < 0 ? margin : width - margin;
			const gap = Math.max(radius * 0.5, Math.abs(to - from) / 24);
			border.push(segment('Rule', from, cy, to, cy, strokeOf(inks[0], thick)));
			for (let x = from + way * gap; (to - x) * way > gap * 0.5; x += way * gap) {
				border.push(diamond('Diamond', x, cy, radius * 0.07, inks[1]));
			}
			border.push(circle('End', to, cy, radius * 0.05, inks[1]));
		}
	} else if (roll.chance(0.7)) {
		const inset = s * 0.06;
		const thick = s * 0.006;
		const square = { cap: 'butt', join: 'miter' } as const;
		border.push(
			rect('Frame', inset, inset, width - inset * 2, height - inset * 2, null, {
				stroke: strokeOf(inks[0], thick, square)
			}),
			rect('Frame', inset * 1.4, inset * 1.4, width - inset * 2.8, height - inset * 2.8, null, {
				stroke: strokeOf(inks[1], thick * 0.5, square)
			})
		);
		for (const [x, y] of [
			[inset, inset],
			[width - inset, inset],
			[width - inset, height - inset],
			[inset, height - inset]
		]) {
			border.push(star('Corner', x, y, inset * 0.42, 4, 0.32, inks[1]));
		}
		if (tall) {
			// Short rules above and below the rosette, each with a diamond.
			for (const way of [-1, 1]) {
				const y = cy + way * radius * 1.25;
				const reach = radius * 0.7;
				border.push(
					segment('Rule', cx - reach, y, cx + reach, y, strokeOf(inks[0], thick * 0.8)),
					diamond('Diamond', cx, y, radius * 0.06, inks[1])
				);
			}
		}
	}

	return [
		rect('Ground', 0, 0, width, height, ground),
		...group('Rosette', flower),
		...group('Border', border)
	];
};

const MAKERS: Record<SurpriseKind, Maker> = {
	night: nightSky,
	mountains,
	waves,
	tiles,
	cutouts,
	orbits,
	rosette
};
